node - <<'NODE'
const {spawn}=require('node:child_process');
const fs=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'monday-cdp-'));
const port=9333;
const p=spawn('/usr/bin/chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-address=127.0.0.1',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore',detached:true});
p.unref();
(async()=>{
 let ok=false,version=null;
 for(let i=0;i<50;i++){
   try{const r=await fetch(`http://127.0.0.1:${port}/json/version`); if(r.ok){version=await r.json();ok=true;break;}}catch{}
   await new Promise(r=>setTimeout(r,100));
 }
 const out={node:process.version,webSocketType:typeof WebSocket,chromium:version?.Browser||null,cdp:ok};
 fs.writeFileSync('browser-primitive.json',JSON.stringify(out));
 try{process.kill(-p.pid,'SIGKILL')}catch{}
 process.exit(0);
})();
